using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RemoteMilitarySuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool retired=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],retired?Old.Value:Heir.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var n=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>n);}}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:military-succession/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0)=>Good(s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision));
    static NewMilitaryInput Request(WorldSession s,bool handover=false)=>Input(s,NewMilitaryAction.Request) with{LedgerPolicy=NewGameMilitary.LedgerIdentityContract,AuthorityPolicy=NewGameMilitary.AuthorityContract,ObservationPolicy=NewGameMilitary.ObservationContract,CycleContract=s.DiagnosticSnapshot().NewMilitary!=null?NewGameMilitary.RenewalContract:null,IssuerPolicy=handover?NewGameMilitary.IssuerSuccessionContract:null};
    static void Succeed(WorldSession s){var id=new EntityId("request:military-head/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir){MilitaryPolicy=NewGameMilitary.CanRetainActiveForSuccession(s.DiagnosticSnapshot(),s.PlayerControl,Owner,Home,s.Seconds,s.Revision)?NewGameMilitary.ActiveSuccessionContract:null},s.PlayerControl,s.Revision));Good(s.ManageHouseSuccession(new(new("request:military-head-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision));At(s,s.Seconds+1);}
    static WorldSession Closed(bool open=true,bool retired=false){var s=Start(retired);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));At(s,s.Seconds+2);Open(s);At(s,s.Seconds+NewGameMilitary.OfferSeconds+3);if(open)Open(s);return s;}
    static WorldSession Changed(){var s=Closed();Succeed(s);return s;}
    static WorldSession Assumed(){var s=Changed();Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));return s;}
    static void Permit(WorldSession s){At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);}
    static void Rice(WorldSession s,long kg)=>Good(s.ManageMilitaryRice(new(new("request:succession-rice/"+s.Revision),NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),kg),s.PlayerControl,s.Revision));
    static void Finish(WorldSession s){Send(s,NewMilitaryAction.Report);At(s,s.Seconds+2);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+2);Open(s);}

    static WorldSession Holding(bool retired=false){var s=Start(retired);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Permit(s);Rice(s,50);Send(s,NewMilitaryAction.Load,20*86400L);s.SetPaused(true);return s;}

    static WorldSession Ready(){var s=Holding(true);Succeed(s);return s;}
    static RemoteMilitaryInput Offer(WorldSession s,long delay=4)=>new(new("request:remote-offer/"+s.Revision),RemoteMilitaryAction.Issue,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Last().Id,Home,s.Seconds+delay);
    static void Remote(WorldSession s,RemoteMilitaryInput i)=>Good(s.SendRemoteMilitary(i,s.PlayerControl,s.Revision));
    static RemoteMilitaryInput Accept(WorldSession s,string id)=>new(new("request:remote-accept/"+s.Revision),RemoteMilitaryAction.Accept,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Last().Id,Original:id);
    static string Issue(WorldSession s,long delay=4){Remote(s,Offer(s,delay));return s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Single().Id;}
    [Fact]public void SealedAndOpenedOfferDoesNotTransferCommandWithoutPersonalAcceptance(){var s=Ready();var id=Issue(s);Assert.Equal(Old,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Accept(s,id),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+5);Open(s);Assert.Equal(Old,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Remote(s,Accept(s,id));Assert.Equal(Heir,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void DeployedAcceptancePreservesArmyUnitsAndStocks(){var s=Ready();var id=Issue(s);At(s,s.Seconds+5);Open(s);Send(s,NewMilitaryAction.Deploy);var before=s.DiagnosticSnapshot();Remote(s,Accept(s,id));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(before.NewMilitary!.Terms,w.NewMilitary!.Terms);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));new WorldSession(w);}
    [Fact]public void DuplicateAndStaleAcceptanceCannotExecuteTwice(){var s=Ready();var id=Issue(s);At(s,s.Seconds+5);Open(s);var i=Accept(s,id);Assert.Equal(ResultCode.StateChanged,s.SendRemoteMilitary(i,s.PlayerControl,s.Revision-1).Code);Remote(s,i);Assert.Equal(ResultCode.AlreadyAccepted,s.SendRemoteMilitary(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Accept(s,id),s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ActiveSuccession!.Entries);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void InvalidAppointmentOrAddressCannotIssue(int n){var s=Ready();var i=Offer(s);i=n switch{0=>i with{MeetAt=s.Seconds},1=>i with{MeetAt=s.Seconds+8*86400},_=>i with{Address=new("site:unknown")}};Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(i,s.PlayerControl,s.Revision).Code);}
    [Fact]public void UnchangedHeadCannotIssue(){var s=Holding(true);Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Offer(s),s.PlayerControl,s.Revision).Code);}
    [Fact]public void NoFailureKnowledgeMeansNoRetry(){var s=Ready();var id=Issue(s);Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(new(new("request:unknown-failure"),RemoteMilitaryAction.Resend,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Last().Id,Original:id),s.PlayerControl,s.Revision).Code);}
    [Fact]public void SignatureForgeryCannotLoad(){var s=Ready();Issue(s);var w=s.DiagnosticSnapshot();var p=w.NewMilitary!.RemoteSuccession!.Papers[0];w.NewMilitary.RemoteSuccession.Papers[0]=p with{Address=new("site:suwa")};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)][InlineData(10)][InlineData(11)]public void GenerationRecoveryPreservesOfferAcceptanceAndFuture(int phase){var s=Ready();var id=Issue(s);if(phase<8){if(phase>=1){At(s,s.Seconds+5);Open(s);}if(phase>=2)Send(s,NewMilitaryAction.Deploy);if(phase>=3)Remote(s,Accept(s,id));if(phase>=4)At(s,s.Seconds+5);if(phase>=5){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Good(s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X-12000,a.Y+4000),B=new(a.X+12000,a.Y+4000)},s.PlayerControl,s.Revision));At(s,s.Seconds+3);}if(phase>=6){Send(s,NewMilitaryAction.Recall);At(s,s.Seconds+50);}if(phase>=7)Send(s,NewMilitaryAction.Enter);}else{FailReport(s,id,phase>=9);if(phase>=10)Remote(s,Retry(s,id));if(phase>=11){var copy=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Last();At(s,Arrival(s,copy.Id)+1);Open(s);Remote(s,Accept(s,copy.Id));}}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"remote-military-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"remote",w.WorldId).Published);var host=new WorldSessionHost(Start(true));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("remote"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"remote-military-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"remote-military-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    static long Arrival(WorldSession s,string id)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==id)).ReadyAt;
    static string FailReport(WorldSession s,string id,bool open=true){s.DiagnosticTransport((m,t)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(m,id));At(s,Arrival(s,id)+2);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==id));At(s,Arrival(s,f.Id)+1);var n=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Single(p=>p.Kind==RemoteMilitaryKind.FailureNotice&&p.Related==id);At(s,Arrival(s,n.Id)+1);if(open)Good(s.Open(s.PlayerControl,new(n.Id),s.Revision));return n.Id;}
    static RemoteMilitaryInput Retry(WorldSession s,string id)=>new(new("request:remote-copy/"+s.Revision),RemoteMilitaryAction.Resend,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Last().Id,Original:id);
    [Fact]public void FailureReportMustArriveAndBeOpenedBeforeRetry(){var s=Ready();var id=Issue(s);var report=FailReport(s,id,false);Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Retry(s,id),s.PlayerControl,s.Revision).Code);Good(s.Open(s.PlayerControl,new(report),s.Revision));Remote(s,Retry(s,id));var ps=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers;var copy=ps.Last();Assert.Equal(id,copy.CopyOf);Assert.Equal(ps[0].Signature,copy.Signature);Assert.Equal(ps[0].Address,copy.Address);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(false)][InlineData(true)]public void RecoveredOriginalAndCopyCannotDoubleTransfer(bool originalFirst){var s=Ready();var id=Issue(s);FailReport(s,id);Remote(s,Retry(s,id));var copy=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Last();if(!originalFirst)At(s,Arrival(s,copy.Id)+1);s.DiagnosticRecoverLocalCourier(id,1);At(s,s.Seconds+1);if(originalFirst)At(s,Arrival(s,copy.Id)+1);Open(s);Remote(s,Accept(s,id));Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Accept(s,copy.Id),s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ActiveSuccession!.Entries);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers,p=>p.Kind==RemoteMilitaryKind.Receipt);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ThreeFailedOffersAreTheHardLimit(){var s=Ready();var id=Issue(s);for(int n=0;n<3;n++){FailReport(s,id);if(n<2){Remote(s,Retry(s,id));id=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Last().Id;}}Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Retry(s,id),s.PlayerControl,s.Revision).Code);Assert.Equal(3,s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Count(p=>p.Kind==RemoteMilitaryKind.Offer));}
    [Fact]public void ExpiredOpenedOfferCannotTransfer(){var s=Ready();var id=Issue(s);At(s,s.Seconds+5);Open(s);var until=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers[0].Until;At(s,until+1);Assert.Equal(ResultCode.NotAvailable,s.SendRemoteMilitary(Accept(s,id),s.PlayerControl,s.Revision).Code);Assert.Equal(Old,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));}
    [Fact]public void OpenedLetterCanBeAcceptedDuringActualRoadMarchWithoutReplacingRoute(){var s=Holding(true);Rice(s,100);Rice(s,100);Send(s,NewMilitaryAction.Load,180*86400L);Succeed(s);var id=Issue(s);At(s,s.Seconds+5);Open(s);Good(s.ManageArmyRoad(new(new("request:remote-road"),ArmyRoadAction.March,new("site:suwa")),s.PlayerControl,s.Revision));At(s,s.Seconds+10);Assert.True(s.ArmyRoadView()!.Marching);var before=s.DiagnosticSnapshot();Remote(s,Accept(s,id));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.ArmyRoad),ContractJson.Write(w.ArmyRoad));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));new WorldSession(w);}

    [Theory][InlineData("Policy")][InlineData("Entries")][InlineData("Papers")][InlineData("Openings")][InlineData("FailureOpenings")]public void ExtensionRequiredFieldsRemainRequired(string field){var s=Ready();Issue(s);var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["NewMilitary"]!["RemoteSuccession"]!.AsObject().Remove(field);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Fact]public void ReceiptRetryRequiresItsOwnPersonallyOpenedPhysicalFailure(){var s=Ready();var id=Issue(s);At(s,s.Seconds+5);Open(s);Remote(s,Accept(s,id));var receipt=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Single(p=>p.Kind==RemoteMilitaryKind.Receipt);s.DiagnosticTransport((m,t)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(m,receipt.Id));At(s,Arrival(s,receipt.Id)+1);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==receipt.Id));At(s,Arrival(s,f.Id)+1);Assert.False(NewGameMilitary.CanSendRemote(s.DiagnosticSnapshot(),Retry(s,receipt.Id)));Good(s.Open(s.PlayerControl,new(f.Id),s.Revision));Remote(s,Retry(s,receipt.Id));var copy=s.DiagnosticSnapshot().NewMilitary!.RemoteSuccession!.Papers.Last();Assert.Equal(receipt.ObservedAt,copy.ObservedAt);Assert.Equal(receipt.Evidence,copy.Evidence);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ActiveSuccession!.Entries);new WorldSession(s.DiagnosticSnapshot());}
}
